'use strict';

const assert = require('node:assert');
const api = require('./solution');
assert.deepStrictEqual(Object.keys(api), ['listNotes', 'insertNote', 'reviseNote', 'removeNote']);
const { listNotes, insertNote, reviseNote, removeNote } = api;

const notes = [
  { key: 0, text: 'first', pinned: false },
  { key: Number.MAX_SAFE_INTEGER, text: '', pinned: true }
];
const before = notes.map(note => ({ ...note }));
const listed = listNotes(notes);
assert.deepStrictEqual(listed, before);
assert.notStrictEqual(listed, notes);
assert.notStrictEqual(listed[0], notes[0]);
listed[0].text = 'changed';
assert.deepStrictEqual(notes, before);
assert.deepStrictEqual(listNotes([]), []);

const newNote = { key: 2, text: 'new', pinned: false };
const inserted = insertNote(notes, newNote);
assert.deepStrictEqual(inserted, [...before, newNote]);
for (let i = 0; i < notes.length; i += 1) assert.notStrictEqual(inserted[i], notes[i]);
assert.notStrictEqual(inserted[2], newNote);
inserted[2].text = 'changed';
assert.strictEqual(newNote.text, 'new');
assert.deepStrictEqual(notes, before);
assert.throws(() => insertNote(notes, { key: 0, text: 'duplicate', pinned: false }), RangeError);

const revised = reviseNote(notes, 0, { text: 'updated', ignored: 123 });
assert.deepStrictEqual(revised, [
  { key: 0, text: 'updated', pinned: false },
  before[1]
]);
assert.notStrictEqual(revised[0], notes[0]);
assert.notStrictEqual(revised[1], notes[1]);
const pinned = reviseNote(notes, Number.MAX_SAFE_INTEGER, { pinned: false });
assert.strictEqual(pinned[1].pinned, false);
assert.strictEqual(pinned[1].text, '');
const absentRevision = reviseNote(notes, 7, { text: 'unused' });
assert.deepStrictEqual(absentRevision, before);
assert.notStrictEqual(absentRevision[0], notes[0]);
assert.deepStrictEqual(notes, before);

const removed = removeNote(notes, 0);
assert.deepStrictEqual(removed, [before[1]]);
assert.notStrictEqual(removed[0], notes[1]);
const absentRemoval = removeNote(notes, 7);
assert.deepStrictEqual(absentRemoval, before);
assert.notStrictEqual(absentRemoval[0], notes[0]);
assert.deepStrictEqual(notes, before);

const malformedNotes = [null, {}, [null], [{ key: -1, text: 'x', pinned: false }], [{ key: 1.2, text: 'x', pinned: false }], [{ key: 0, text: 1, pinned: false }], [{ key: 0, text: 'x', pinned: 0 }]];
for (const bad of malformedNotes) {
  assert.throws(() => listNotes(bad), TypeError);
}
const duplicateNotes = [
  { key: 1, text: 'a', pinned: false },
  { key: 1, text: 'b', pinned: true }
];
assert.throws(() => listNotes(duplicateNotes), RangeError);
for (const badNote of [null, {}, { key: -1, text: 'x', pinned: false }, { key: 3, text: 1, pinned: false }, { key: 3, text: 'x', pinned: 'no' }]) {
  assert.throws(() => insertNote([], badNote), TypeError);
}
for (const badKey of [-1, 1.5, Number.MAX_SAFE_INTEGER + 1, '0']) {
  assert.throws(() => reviseNote([], badKey, { text: 'x' }), TypeError);
  assert.throws(() => removeNote([], badKey), TypeError);
}
for (const changes of [null, undefined, 1, {}, { text: 1 }, { pinned: 'yes' }, { other: true }]) {
  assert.throws(() => reviseNote(notes, 0, changes), TypeError);
}

